import numpy as np


def patchify(image, p):
    h, w, c = image.shape
    if h % p or w % p:
        raise ValueError("image sides must be multiples of p")
    grid = image.reshape(h // p, p, w // p, p, c).transpose(0, 2, 1, 3, 4)
    return grid.reshape(-1, p * p * c)
